import { brotliDecompressSync, gunzipSync, inflateRawSync, inflateSync } from "node:zlib";

function decodeRequestBody(bytes, contentEncoding) {
  if (!contentEncoding) return bytes;
  const encodings = String(contentEncoding)
    .split(",")
    .map((part) => part.split(";", 1)[0].trim().toLowerCase())
    .filter(Boolean)
    .filter((enc) => enc && enc !== "identity");
  if (encodings.length === 0) return bytes;
  let data = Buffer.isBuffer(bytes) ? bytes : Buffer.from(bytes);
  // Content-Encoding lists transforms in the order applied, so decode in reverse.
  for (let i = encodings.length - 1; i >= 0; i -= 1) {
    const enc = encodings[i];
    if (enc === "gzip" || enc === "x-gzip") {
      data = gunzipSync(data);
    } else if (enc === "deflate") {
      try {
        data = inflateSync(data);
      } catch {
        data = inflateRawSync(data);
      }
    } else if (enc === "br") {
      data = brotliDecompressSync(data);
    } else if (enc === "zstd") {
      const fn = globalThis.Bun && globalThis.Bun.zstdDecompressSync;
      if (typeof fn !== "function") throw new Error("zstd unsupported");
      const out = fn(data);
      data = Buffer.isBuffer(out) ? out : Buffer.from(out);
    } else {
      throw new Error("unsupported content-encoding: " + enc);
    }
  }
  return data;
}

